def fingerprint(raw):
    return hashlib.md5(raw.replace(b"\r\n", b"\n")).hexdigest()


def main():
    if os.path.basename(os.getcwd()) == "documentation":
        raise SystemExit("ERROR: run this from the GALLERY repo ROOT, next to "
                         "index.html -- not from documentation/. "
                         "NOTHING was written.")
    if os.path.isfile("palomas_orrery.py"):
        raise SystemExit("ERROR: this is the ORRERY repo. This patch belongs "
                         "in the GALLERY repo (tonyquintanilla.github.io). "
                         "NOTHING was written.")
    if not (os.path.isfile("index.html") and os.path.isfile("interactive.html")):
        raise SystemExit("ERROR: index.html and interactive.html are not both "
                         "here, so this is not the gallery root. NOTHING was "
                         "written.")
    for path in list(SPEC["NEW_TEXT"]) + list(SPEC["NEW_BIN"]):
        if os.path.exists(path):
            raise SystemExit("ERROR: %s already exists. If you already ran "
                             "this patch, it has nothing left to do. NOTHING "
                             "was written." % path)
    pictures = {}
    for path, (md5, data) in SPEC["NEW_BIN"].items():
        raw = base64.b64decode(data)
        if hashlib.md5(raw).hexdigest() != md5:
            raise SystemExit("ERROR: the picture carried in this script is "
                             "damaged (%s). NOTHING was written." % path)
        pictures[path] = raw

    results = []
    for path, edits in sorted(SPEC["PLAN"].items()):
        with open(path, "rb") as handle:
            raw = handle.read()
        got = fingerprint(raw)
        if got != SPEC["BASE"][path]:
            raise SystemExit(
                "ERROR: %s is not the file this patch was built against.\n"
                "       expected %s, found %s.\n"
                "       (Line endings are excluded, so they are not the cause.)\n"
                "       If the gallery editor saved since df8bbab, that is the\n"
                "       likely reason; tell Claude.\n"
                "       NOTHING was written. Undo is Discard Changes in\n"
                "       GitHub Desktop." % (path, SPEC["BASE"][path], got))
        crlf = raw.count(b"\r\n") > 0
        nl = "\r\n" if crlf else "\n"
        text = raw.decode("utf-8")
        before = sum(1 for ch in text if ord(ch) > 127)
        done = []
        for old, new, label in edits:
            o = old.replace("\n", nl)
            n = new.replace("\n", nl)
            count = text.count(o)
            if count != 1:
                raise SystemExit("ANCHOR FAIL (%s): expected 1 match in %s, "
                                 "found %d. NOTHING was written."
                                 % (label, path, count))
            text = text.replace(o, n)
            done.append(label)
        if sum(1 for ch in text if ord(ch) > 127) > before:
            raise SystemExit("ERROR: %s would hold new non-ASCII text. "
                             "NOTHING was written." % path)
        results.append((path, text, done, crlf))

    for path, text, done, crlf in results:
        with open(path, "wb") as handle:
            handle.write(text.encode("utf-8"))
        for label in done:
            print("ok  %-34s %s%s" % (path, label, "  [CRLF]" if crlf else ""))
    for path, content in sorted(SPEC["NEW_TEXT"].items()):
        folder = os.path.dirname(path)
        if folder and not os.path.isdir(folder):
            os.makedirs(folder)
        with open(path, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(content)
        print("ok  %-34s created" % path)
    for path, raw in sorted(pictures.items()):
        folder = os.path.dirname(path)
        if folder and not os.path.isdir(folder):
            os.makedirs(folder)
        with open(path, "wb") as handle:
            handle.write(raw)
        print("ok  %-34s created (%d bytes)" % (path, len(raw)))

    print("")
    print("Stamp updated: index.html's header (October 4, 2026).")
    print("")
    print("patch applied")
    print("")
    print("NEXT:")
    print("  1. If the gallery editor is open, use File > Reload from disk")
    print("     before anything else in it. An open editor does not see")
    print("     this patch's changes, and its Save All would write over them.")
    print("  2. python gallery_maintenance_run.py (VS Code, Run).")
    print("     Expect 23 of 23. None of its checks reads the lobby, so")
    print("     this says the patch broke nothing else; the phone is the")
    print("     check of the lobby itself.")
    print("  3. Move this script into documentation/; commit and push, in")
    print("     a commit of its own -- not with the Sun's distance-card")
    print("     files from the other session. No cache rebuild is needed.")
    print("  4. On your phone: close the tab, then open palomasorrery.com.")
    print("     - The wide card at the top of Featured: the picture, the")
    print("       words, the Interactive tag. The other cards below it.")
    print("     - The three doors, with no rooms under construction.")
    print("     - Tap the wide card: the Solar System room opens.")
    print("     - Back, then the SOLAR SYSTEM door: the wide card first,")
    print("       and no \"solar_system\" row at the foot of Rooms.")
    print("     Then turn the phone sideways, then the desktop.")


if __name__ == "__main__":
    main()
